"""Writes unicode_tables.go: the three character classes the Python renderers
use (category C*, category M*, East Asian width W or F), as sorted ranges.

Run from internal/render: python3 -I testdata/gen/unicode_tables.py > unicode_tables.go
"""
import sys
import unicodedata


def ranges(pred):
    out, start = [], None
    for cp in range(0x110000):
        hit = pred(chr(cp))
        if hit and start is None:
            start = cp
        elif not hit and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, 0x10FFFF))
    return out


def emit(name, doc, table, last=False):
    print(f"// {name} {doc}")
    print(f"var {name} = []runeRange{{")
    for lo, hi in table:
        print(f"\t{{0x{lo:04X}, 0x{hi:04X}}},")
    print("}")
    if not last:
        print()


print("// Code generated by testdata/gen/unicode_tables.py; DO NOT EDIT.")
print(f"// Unicode {unicodedata.unidata_version}, the database of the Python the old renderers ran on.")
print()
print("package render")
print()
emit("controlRanges", "holds the code points whose category starts with C.",
     ranges(lambda c: unicodedata.category(c).startswith("C")))
emit("markRanges", "holds the code points whose category starts with M.",
     ranges(lambda c: unicodedata.category(c).startswith("M")))
emit("wideRanges", "holds the code points whose East Asian width is W or F.",
     ranges(lambda c: unicodedata.east_asian_width(c) in ("W", "F")), last=True)
